-- food menu snapshots, batch 8 (25 menus)
with target as (
  select slug from venues where slug = 'wanna-jungle-pool-and-bar-at-the-kayon-jungle-resort' and status = 'active' and publication_status = 'published'
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'KePitu Restaurant Menu', 1, 'draft', 'partial', 'https://thekayonjungleresort.com/kepitu-restaurant-menu', 'Official Wanna Jungle Pool and Bar at The Kayon Jungle Resort menu',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'aeea6eb648d814874447e4030b82cd25dfa2e6d1528c3263f52dd9de4bf8a4d7', 'food'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'food')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('APPETIZER', 0)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('APPETIZER', 'CAESAR SALAD', 'Baby romaine, crispy bacon, Parmesan cheese, egg, classic Caesar dressing, prawn, chicken, and garlic bread.', 145000, 'IDR', 0), ('APPETIZER', 'PORK BELLY SALAD', 'Crispy pork belly with pomelo, cucumber, coconut, coriander, chili, cashew nuts, and tamarind sauce.', 135000, 'IDR', 1), ('APPETIZER', 'THAI BEEF SALAD', 'Pan-fried beef tenderloin with young mango, coriander, red onion, chili, and lemongrass.', 155000, 'IDR', 2), ('APPETIZER', 'PRAWN POMELO SALAD', 'Grilled king prawn with pomelo, coconut, young mango, coriander, iceberg lettuce, chili, onion, and nam jim sauce.', 135000, 'IDR', 3), ('APPETIZER', 'GADO - GADO', 'Traditional Indonesian salad with bean sprouts, spinach, cabbage, long beans, carrot, egg, tempeh, tofu, cucumber, and peanut sauce.', 105000, 'IDR', 4), ('APPETIZER', 'CHICKEN OR FISH FINGER', 'Crispy breaded chicken or fish served with French fries, and tartar sauce.', 110000, 'IDR', 5), ('APPETIZER', 'VEGETABLES SPRING ROLL', 'Vegetable spring rolls served with lettuce, chili sauce, tamarind sauce, and sweet-spicy chili sauce.', 100000, 'IDR', 6), ('APPETIZER', 'CHICKEN SALAD', 'Grilled chicken breast with couscous, orange, onion, avocado, mixed greens, beetroot, and lemon dressing.', 125000, 'IDR', 7), ('APPETIZER', 'TUNA TARTARE', 'Fresh tuna with lime, avocado, wasabi, coriander, poached egg, and crispy wonton cone.', 125000, 'IDR', 8), ('APPETIZER', 'SALMON CARPACCIO', 'Marinated salmon with dill, pomegranate, sour cream, tobiko, mixed greens, and chili oil.', 190000, 'IDR', 9), ('APPETIZER', 'OCTOPUS SALAD', 'Slow-cooked baby octopus with apple, carrot-ginger purée, mixed greens, hummus, and olive oil.', 135000, 'IDR', 10), ('APPETIZER', 'CRISPY CALAMARY', 'Five-spice calamari rings with curry leaves, chili, ginger flower, lettuce, and spicy soy mayo.', 135000, 'IDR', 11), ('APPETIZER', 'SCALLOP AND PRAWN SALAD', 'Hokkaido scallops and prawns with tomato mousse, pea purée, herbs, baby radish, lettuce, cherry tomatoes, and pesto sauce.', 165000, 'IDR', 12), ('APPETIZER', 'COCONUT PRAWN', 'Crispy fried prawns with coconut, served with iceberg lettuce, Thai salad, and cashew nuts.', 150000, 'IDR', 13)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

